let websocket = null;
let pluginUUID = null;
let backtrackWs = null;
let isBacktrackConnected = false;

let backtrackState = {
  obs_connected: false,
  is_recording: false,
  preferred_clip_length_seconds: 60,
  record_duration_ms: 0,
  main_record_start_time_ms: 0,
  replay_buffers: [],
  record_sources: []
};

const RAW_ICONS = {"tray": "data:image/png;base64,", "replay_green": "data:image/png;base64,", "record_red": "data:image/png;base64,", "record_stop": "data:image/png;base64,", "bookmark": "data:image/png;base64,", "cancel_idle": "data:image/png;base64,", "cancel_active": "data:image/png;base64,", "replay_yellow": "data:image/png;base64,"};
const loadedImages = {};

for (const [k, b64] of Object.entries(RAW_ICONS)) {
  const img = new Image();
  img.src = b64;
  loadedImages[k] = img;
}

const actionContexts = new Map();
const animationStates = new Map();
const localRecordStartTimes = new Map();
const lastKnownSourceMap = new Map();

function connectElgatoStreamDeckSocket(inPort, inPluginUUID, inRegisterEvent, inInfo) {
  pluginUUID = inPluginUUID;
  websocket = new WebSocket('ws://127.0.0.1:' + inPort);

  websocket.onopen = function () {
    websocket.send(JSON.stringify({ event: inRegisterEvent, uuid: inPluginUUID }));
    initBacktrackBridge();
    startTimerLoop();
  };

  websocket.onmessage = function (evt) {
    const jsonObj = JSON.parse(evt.data);
    const event = jsonObj.event;
    const action = jsonObj.action;
    const context = jsonObj.context;

    if (event === 'willAppear') {
      const settings = jsonObj.payload.settings || {};
      const controller = jsonObj.payload.controller || (action.includes('dial') ? 'Encoder' : 'Keypad');
      const isEncoder = controller === 'Encoder' || action.includes('dial');
      actionContexts.set(context, { action, settings, controller, isEncoder });
      if (settings.source || settings.last_known_source) {
        lastKnownSourceMap.set(context, settings.source || settings.last_known_source);
      }
      if (isEncoder) {
        setFeedbackLayout(context, 'layouts/touch_strip.json');
      }
      setTitle(context, '');
      renderKey(context, true);
    } else if (event === 'willDisappear') {
      actionContexts.delete(context);
      animationStates.delete(context);
      localRecordStartTimes.delete(context);
    } else if (event === 'didReceiveSettings') {
      const entry = actionContexts.get(context);
      if (entry) {
        entry.settings = jsonObj.payload.settings || {};
        if (entry.settings.source || entry.settings.last_known_source) {
          lastKnownSourceMap.set(context, entry.settings.source || entry.settings.last_known_source);
        }
        renderKey(context, true);
      }
    } else if (event === 'keyDown') {
      handleKeyAction(context);
    } else if (event === 'dialRotate') {
      handleDialRotate(context, jsonObj.payload.ticks);
    } else if (event === 'dialDown' || event === 'dialPress') {
      handleDialPress(context);
    } else if (event === 'touchTap') {
      handleTouchTap(context, jsonObj.payload);
    }
  };
}

function initBacktrackBridge() {
  if (backtrackWs) {
    try { backtrackWs.close(); } catch (e) {}
  }

  backtrackWs = new WebSocket('ws://127.0.0.1:44558/ws');

  backtrackWs.onopen = function () {
    isBacktrackConnected = true;
    backtrackWs.send(JSON.stringify({ action: 'get_state' }));
    renderAllKeys(true);
  };

  backtrackWs.onmessage = function (evt) {
    try {
      const msg = JSON.parse(evt.data);
      if (msg.event === 'state_snapshot') {
        backtrackState = msg.data;
        renderAllKeys(false);
      } else if (msg.event === 'replay_saving') {
        triggerSavingAnimation(msg.data.source);
      } else if (msg.event === 'replay_saved') {
        triggerSavedAnimation(msg.data.key);
      } else if (msg.event === 'bookmark_added') {
        triggerBookmarkAnimation();
      } else if (msg.event === 'recording_state') {
        backtrackState.is_recording = msg.data.active;
        if (backtrackWs && backtrackWs.readyState === WebSocket.OPEN) {
          backtrackWs.send(JSON.stringify({ action: 'get_state' }));
        }
        renderAllKeys(true);
      }
    } catch (e) {}
  };

  backtrackWs.onclose = function () {
    isBacktrackConnected = false;
    backtrackState.obs_connected = false;
    renderAllKeys(true);
    setTimeout(initBacktrackBridge, 2000);
  };
  backtrackWs.onerror = function () {
    isBacktrackConnected = false;
    backtrackState.obs_connected = false;
    renderAllKeys(true);
    try { backtrackWs.close(); } catch (e) {}
  };
}

function matchesClipSource(context, entry, targetIdentifier) {
  if (!targetIdentifier) return false;
  const s = (entry.settings.source || lastKnownSourceMap.get(context) || '').trim().toLowerCase();
  const target = targetIdentifier.trim().toLowerCase();

  const buf = findReplayBuffer(s);
  if (buf && buf.status !== 1) {
    return false;
  }

  if (s === target) return true;

  if (buf) {
    if (buf.key && buf.key.toLowerCase() === target) return true;
    if (buf.source && buf.source.toLowerCase() === target) return true;
    if (buf.label && buf.label.toLowerCase() === target) return true;
    if (buf.raw_label && buf.raw_label.toLowerCase() === target) return true;
    if (buf.dest && buf.dest.toLowerCase().includes(target)) return true;
  }

  if (s && s !== 'main' && s !== 'full scene') {
    return s.includes(target) || target.includes(s);
  }

  if ((!s || s === 'main' || s === 'full scene') && (target === 'main' || target === 'full scene')) {
    return buf ? buf.status === 1 : false;
  }

  return false;
}

const activeBurstIntervals = new Map();

function runBurstAnimation(context, durationMs) {
  if (activeBurstIntervals.has(context)) {
    clearInterval(activeBurstIntervals.get(context));
  }
  const start = Date.now();
  const interval = setInterval(() => {
    const elapsed = Date.now() - start;
    if (elapsed > durationMs || !actionContexts.has(context)) {
      clearInterval(interval);
      activeBurstIntervals.delete(context);
      renderKey(context, true);
      return;
    }
    renderKey(context, true);
  }, 16);
  activeBurstIntervals.set(context, interval);
}

function triggerSavingAnimation(source, triggerContext = null) {
  const now = Date.now();
  for (const [context, entry] of actionContexts) {
    if (entry.action === 'com.ilyambr.backtrack.clip' || entry.action === 'com.ilyambr.backtrack.cliplengthdial') {
      if (context === triggerContext || matchesClipSource(context, entry, source)) {
        let anim = animationStates.get(context) || {};
        anim.savingUntil = now + 45000;
        anim.savedUntil = 0;
        animationStates.set(context, anim);
        runBurstAnimation(context, 45000);
      }
    }
  }
}

function triggerSavedAnimation(key) {
  const now = Date.now();
  for (const [context, entry] of actionContexts) {
    if (entry.action === 'com.ilyambr.backtrack.clip' || entry.action === 'com.ilyambr.backtrack.cliplengthdial') {
      if (!key || matchesClipSource(context, entry, key)) {
        if (activeBurstIntervals.has(context)) {
          clearInterval(activeBurstIntervals.get(context));
          activeBurstIntervals.delete(context);
        }
        let anim = animationStates.get(context) || {};
        anim.savingUntil = 0;
        anim.savedUntil = now + 1800;
        animationStates.set(context, anim);
        runBurstAnimation(context, 1800);
      }
    }
  }
}

function triggerBookmarkAnimation() {
  const now = Date.now();
  for (const [context, entry] of actionContexts) {
    if (entry.action === 'com.ilyambr.backtrack.bookmark') {
      let anim = animationStates.get(context) || {};
      anim.bookmarkUntil = now + 900;
      animationStates.set(context, anim);
      runBurstAnimation(context, 900);
    }
  }
}

function handleKeyAction(context) {
  const entry = actionContexts.get(context);
  if (!entry || !backtrackWs || backtrackWs.readyState !== WebSocket.OPEN) return;

  const action = entry.action;
  const source = entry.settings.source || lastKnownSourceMap.get(context) || 'main';

  if (action === 'com.ilyambr.backtrack.clip') {
    const buffer = findReplayBuffer(source);
    if (buffer && buffer.status === 0) {
      return;
    }
    triggerSavingAnimation(source, context);
    backtrackWs.send(JSON.stringify({ action: 'save_replay', source }));
  } else if (action === 'com.ilyambr.backtrack.record') {
    const rec = findRecordSource(source);
    if (rec && rec.status === 0) {
      return;
    }
    backtrackWs.send(JSON.stringify({ action: 'toggle_record', source }));
  } else if (action === 'com.ilyambr.backtrack.cancel') {
    backtrackWs.send(JSON.stringify({ action: 'cancel_recording', source }));
  } else if (action === 'com.ilyambr.backtrack.bookmark') {
    triggerBookmarkAnimation();
    backtrackWs.send(JSON.stringify({ action: 'add_bookmark' }));
  } else if (action === 'com.ilyambr.backtrack.hud') {
    backtrackWs.send(JSON.stringify({ action: 'toggle_hud' }));
  }
}

let timerLoopInterval = null;
function startTimerLoop() {
  if (timerLoopInterval) return;
  timerLoopInterval = setInterval(() => {
    renderAllKeys(false);
  }, 1000);
}

function findReplayBuffer(sourceName) {
  if (!backtrackState.replay_buffers || backtrackState.replay_buffers.length === 0) return null;
  const s = (sourceName || '').trim().toLowerCase();

  if (!s || s === 'main' || s === 'full scene') {
    const mainBuf = backtrackState.replay_buffers.find(b => b.key === 'main' || (b.label && b.label.toLowerCase() === 'replay buffer'));
    if (mainBuf) return mainBuf;
    return backtrackState.replay_buffers[0];
  }

  let match = backtrackState.replay_buffers.find(b =>
    (b.key && b.key.toLowerCase() === s) ||
    (b.label && b.label.toLowerCase() === s) ||
    (b.raw_label && b.raw_label.toLowerCase() === s) ||
    (b.source && b.source.toLowerCase() === s)
  );
  if (match) return match;

  match = backtrackState.replay_buffers.find(b =>
    (b.label && b.label.toLowerCase().includes(s)) ||
    (b.raw_label && b.raw_label.toLowerCase().includes(s)) ||
    (b.source && b.source.toLowerCase().includes(s))
  );
  if (match) return match;

  return null;
}

function findRecordSource(sourceName) {
  if (!backtrackState.record_sources || backtrackState.record_sources.length === 0) return null;
  const s = (sourceName || '').trim().toLowerCase();

  if (!s || s === 'main' || s === 'full scene') {
    return null;
  }

  let match = backtrackState.record_sources.find(r =>
    (r.key && r.key.toLowerCase() === s) ||
    (r.label && r.label.toLowerCase() === s) ||
    (r.raw_label && r.raw_label.toLowerCase() === s) ||
    (r.source && r.source.toLowerCase() === s)
  );
  if (match) return match;

  match = backtrackState.record_sources.find(r =>
    (r.label && r.label.toLowerCase().includes(s)) ||
    (r.raw_label && r.raw_label.toLowerCase().includes(s)) ||
    (r.source && r.source.toLowerCase().includes(s))
  );
  if (match) return match;

  return null;
}

function isSourceRecording(sourceName) {
  if (!isBacktrackConnected || !backtrackState.obs_connected) return false;
  const s = (sourceName || '').trim().toLowerCase();

  if (!s || s === 'main' || s === 'full scene') {
    return backtrackState.is_main_recording === true || backtrackState.main_record_start_time_ms > 0;
  }

  const rec = findRecordSource(sourceName);
  if (rec) {
    return rec.status === 2 || rec.is_recording === true;
  }

  return false;
}

function renderAllKeys(force = false) {
  for (const [context] of actionContexts) {
    renderKey(context, force);
  }
}

function renderKey(context, force = false) {
  const entry = actionContexts.get(context);
  if (!entry) return;

  const now = Date.now();
  const anim = animationStates.get(context) || {};
  const action = entry.action;
  const configuredSource = (entry.settings.source || '').trim();
  const isMainTarget = !configuredSource || configuredSource.toLowerCase() === 'main' || configuredSource.toLowerCase() === 'full scene';

  const isOnline = isBacktrackConnected && backtrackState.obs_connected;

  let iconImg = loadedImages.tray;
  let header = isMainTarget ? 'Main' : configuredSource;
  let dotColor = null;
  let footer = '';
  let footerSub = null;
  let footerColor = '#3ECF8E';
  let footerFont = 'bold 22px "Segoe UI", sans-serif';
  let isActive = false;
  let isRecording = false;
  let isSaving = anim.savingUntil > now;
  let isSaved = anim.savedUntil > now;
  let isBookmarking = anim.bookmarkUntil > now;
  let rotationAngle = 0;
  const pulsePhase = Math.sin(((now % 1300) / 1300) * Math.PI * 2);

  if (action === 'com.ilyambr.backtrack.hud') {
    header = 'Backtrack';
    if (!isBacktrackConnected) {
      isActive = false;
      dotColor = '#FF3B30';
      footer = 'DISCONNECTED';
      footerSub = null;
      footerColor = '#FF3B30';
      footerFont = '900 15px "Segoe UI", sans-serif';
      iconImg = loadedImages.tray;
    } else if (backtrackState.obs_connected) {
      isActive = true;
      dotColor = '#3ECF8E';
      footer = 'OBS';
      footerSub = 'CONNECTED';
      footerColor = '#3ECF8E';
      footerFont = '900 16.5px "Segoe UI", sans-serif';
      iconImg = loadedImages.tray;
    } else {
      isActive = true;
      dotColor = '#FF3B30';
      footer = 'OBS';
      footerSub = 'DISCONNECTED';
      footerColor = '#FF3B30';
      footerFont = '900 15px "Segoe UI", sans-serif';
      iconImg = loadedImages.tray;
    }
  } else if (action === 'com.ilyambr.backtrack.clip') {
    const buffer = findReplayBuffer(configuredSource);
    if (isMainTarget) {
      header = 'Main';
    } else {
      header = (buffer && buffer.label) ? buffer.label : (configuredSource || 'Screen');
    }

    if (isOnline) {
      const isBufferActive = buffer ? buffer.status === 1 : false;

      if (isSaving) {
        isActive = true;
        dotColor = '#F59E0B';
        footer = 'SAVING...';
        footerSub = null;
        footerColor = '#F59E0B';
        footerFont = 'bold 16px "Segoe UI", sans-serif';
        iconImg = loadedImages.replay_yellow || loadedImages.replay_green;
      } else if (isSaved) {
        isActive = true;
        dotColor = '#3ECF8E';
        footer = 'SAVED!';
        footerSub = null;
        footerColor = '#3ECF8E';
        footerFont = 'bold 18px "Segoe UI", sans-serif';
        iconImg = loadedImages.replay_green;
      } else if (isBufferActive) {
        isActive = true;
        dotColor = '#3ECF8E';
        const length = (backtrackState.preferred_clip_length_seconds > 0)
          ? backtrackState.preferred_clip_length_seconds
          : (buffer && buffer.length > 0 ? buffer.length : 60);
        footer = length >= 60 && (length % 60 === 0) ? `${Math.floor(length / 60)}:00` : (length >= 60 ? `${Math.floor(length / 60)}:${String(length % 60).padStart(2, '0')}` : `${length}s`);
        footerSub = null;
        footerColor = '#3ECF8E';
        footerFont = 'bold 22px "Segoe UI", sans-serif';
        iconImg = loadedImages.replay_green;
      } else {
        isActive = false;
        dotColor = 'rgba(255,255,255,0.15)';
        footer = 'INACTIVE';
        footerSub = null;
        footerColor = '#555555';
        footerFont = 'bold 15px "Segoe UI", sans-serif';
        iconImg = loadedImages.replay_green;
      }
    } else {
      isActive = false;
      footer = 'OFFLINE';
      footerSub = null;
      footerColor = '#555555';
      dotColor = 'rgba(255,255,255,0.15)';
      footerFont = 'bold 15px "Segoe UI", sans-serif';
      iconImg = loadedImages.replay_green;
    }
  } else if (action === 'com.ilyambr.backtrack.record') {
    let rec = null;
    if (isMainTarget) {
      header = 'Main';
      isRecording = backtrackState.is_main_recording === true || (backtrackState.main_record_start_time_ms > 0);
    } else {
      rec = findRecordSource(configuredSource);
      header = (rec && rec.label) ? rec.label : (configuredSource || 'Screen');
      isRecording = rec ? (rec.status === 2 || rec.is_recording === true) : false;
    }

    if (isOnline) {
      if (isRecording) {
        isActive = true;
        iconImg = loadedImages.record_stop;

        let startTime = 0;
        if (isMainTarget) {
          if (backtrackState.main_record_start_time_ms > 0) {
            startTime = backtrackState.main_record_start_time_ms;
          } else if (backtrackState.record_duration_ms > 0) {
            startTime = now - backtrackState.record_duration_ms;
          }
        } else if (rec) {
          if (rec.start_time_ms > 0) {
            startTime = rec.start_time_ms;
          } else if (rec.duration_ms > 0) {
            startTime = now - rec.duration_ms;
          }
        }

        if (!startTime || startTime <= 0) {
          startTime = localRecordStartTimes.get(context);
          if (!startTime) {
            startTime = now;
            localRecordStartTimes.set(context, startTime);
          }
        } else {
          localRecordStartTimes.set(context, startTime);
        }

        const elapsedSec = Math.max(0, Math.floor((now - startTime) / 1000));
        const m = String(Math.floor(elapsedSec / 60)).padStart(2, '0');
        const s = String(elapsedSec % 60).padStart(2, '0');
        footer = `${m}:${s}`;
        footerSub = null;
        footerColor = '#FF0000';
        dotColor = '#FF0000';
        footerFont = 'bold 22px "Segoe UI", sans-serif';
      } else {
        localRecordStartTimes.delete(context);
        let isReady = true;
        let isInactive = false;

        if (!isMainTarget) {
          isReady = rec ? (rec.status === 1 || rec.status === undefined) : false;
          isInactive = !rec || rec.status === 0;
        }

        if (isReady && !isInactive) {
          isActive = true;
          iconImg = loadedImages.record_red;
          footer = 'STOPPED';
          footerSub = null;
          footerColor = '#888888';
          dotColor = 'rgba(255,255,255,0.15)';
          footerFont = 'bold 15px "Segoe UI", sans-serif';
        } else {
          isActive = false;
          iconImg = loadedImages.record_red;
          footer = 'INACTIVE';
          footerSub = null;
          footerColor = '#555555';
          dotColor = 'rgba(255,255,255,0.15)';
          footerFont = 'bold 15px "Segoe UI", sans-serif';
        }
      }
    } else {
      localRecordStartTimes.delete(context);
      isActive = false;
      footer = 'OFFLINE';
      footerSub = null;
      footerColor = '#555555';
      dotColor = 'rgba(255,255,255,0.15)';
      footerFont = 'bold 15px "Segoe UI", sans-serif';
      iconImg = loadedImages.record_red;
    }
  } else if (action === 'com.ilyambr.backtrack.cancel') {
    header = 'CANCEL';
    footer = '';
    footerSub = null;
    dotColor = null;
    if (isOnline) {
      if (backtrackState.is_recording) {
        isActive = true;
        iconImg = loadedImages.cancel_idle;
      } else {
        isActive = false;
        iconImg = loadedImages.cancel_idle;
      }
    } else {
      isActive = false;
      iconImg = loadedImages.cancel_idle;
    }
  } else if (action === 'com.ilyambr.backtrack.bookmark') {
    header = 'Bookmark';
    footer = '';
    footerSub = null;
    dotColor = null;
    if (isOnline) {
      isActive = true;
      iconImg = loadedImages.bookmark;
    } else {
      isActive = false;
      iconImg = loadedImages.bookmark;
    }
  } else if (action === 'com.ilyambr.backtrack.cliplengthdial') {
    const targetSource = entry.settings.source || lastKnownSourceMap.get(context) || 'main';
    const buf = findReplayBuffer(targetSource);
    const rawName = buf ? (buf.label || buf.raw_label || 'Main') : (targetSource === 'main' ? 'Main' : targetSource);
    const displayName = `Clip ${rawName}`;

    header = displayName;
    const curSec = (buf && (buf.length > 0 || buf.length_seconds > 0)) ? (buf.length || buf.length_seconds) : (backtrackState.preferred_clip_length_seconds || 60);
    const durLabel = curSec >= 60 ? (curSec % 60 === 0 ? `${curSec / 60}m` : `${Math.floor(curSec / 60)}m ${curSec % 60}s`) : `${curSec}s`;
    
    footer = durLabel;
    footerSub = null;
    dotColor = null;
    const isBufferActive = isOnline && (buf ? buf.status === 1 : false);
    isActive = isBufferActive;

    if (isOnline) {
      if (isBufferActive) {
        iconImg = isSaving ? (loadedImages.replay_yellow || loadedImages.replay_green) : loadedImages.replay_green;
      } else {
        iconImg = loadedImages.replay_green;
      }
    } else {
      isActive = false;
      iconImg = loadedImages.replay_green;
    }

    if (entry.controller === 'Encoder' || entry.isEncoder) {
      const subTextLabel = !isOnline
        ? 'Offline'
        : (!isBufferActive
          ? 'Inactive'
          : (isSaving ? 'Saving...' : (isSaved ? 'Clip Saved!' : 'Tap to Reset')));

      const touchDataUrl = drawTouchStripCanvas(touchStripCtx, {
        header: displayName,
        valueText: durLabel,
        subText: subTextLabel,
        iconImg,
        isActive,
        isSaving,
        isSaved,
        pulsePhase,
        accentColor: '#3ECF8E'
      });

      setFeedback(context, {
        "full-canvas": touchDataUrl,
        "canvas": touchDataUrl,
        title: '',
        value: '',
        indicator: {
          enabled: false
        }
      });

      setImage(context, touchDataUrl);
      return;
    }
  }

  const animFrame = isSaving ? Math.floor((now % 1300) / 16) : (isBookmarking ? Math.floor((anim.bookmarkUntil - now) / 16) : 0);
  const stateKey = `${action}|${header}|${footer}|${footerSub}|${footerColor}|${dotColor}|${isActive}|${isRecording}|${animFrame}|${isSaved}|${isBookmarking}`;
  if (!force && anim.lastRenderKey === stateKey) {
    return;
  }
  anim.lastRenderKey = stateKey;
  animationStates.set(context, anim);

  const dataUrl = drawKeycapCanvas(globalCtx, {
    header,
    dotColor,
    iconImg,
    footer,
    footerSub,
    footerColor,
    footerFont,
    isActive,
    isSaving,
    isSaved,
    isBookmarking,
    pulsePhase,
    animBookmarkUntil: anim.bookmarkUntil,
    now
  });

  setImage(context, dataUrl);
}

const BASE_DURATION_STEPS = [15, 30, 45, 60, 75, 90, 100, 120, 150, 180, 210, 240, 300, 360, 420, 480, 540, 600, 720, 900, 1080, 1200, 1500, 1800, 2400, 3600];

function getDynamicDurationSteps() {
  const maxBufferSec = (backtrackState.replay_buffer_minutes && backtrackState.replay_buffer_minutes > 0)
    ? backtrackState.replay_buffer_minutes * 60
    : 1800;

  const filtered = BASE_DURATION_STEPS.filter(s => s <= maxBufferSec);
  if (filtered.length === 0 || filtered[filtered.length - 1] < maxBufferSec) {
    filtered.push(maxBufferSec);
  }
  return filtered;
}

function handleDialRotate(context, ticks) {
  const entry = actionContexts.get(context);
  const targetSource = (entry && entry.settings && entry.settings.source) || lastKnownSourceMap.get(context) || 'main';
  const buf = findReplayBuffer(targetSource);

  const steps = getDynamicDurationSteps();
  const curSec = (buf && (buf.length > 0 || buf.length_seconds > 0)) ? (buf.length || buf.length_seconds) : (backtrackState.preferred_clip_length_seconds || 60);
  let idx = steps.indexOf(curSec);
  if (idx === -1) {
    idx = steps.findIndex(s => s >= curSec);
    if (idx === -1) idx = steps.length - 1;
  }

  if (ticks > 0) {
    idx = Math.min(steps.length - 1, idx + 1);
  } else if (ticks < 0) {
    idx = Math.max(0, idx - 1);
  }

  const nextSec = steps[idx];
  if (buf) {
    buf.length = nextSec;
    buf.length_seconds = nextSec;
  } else {
    backtrackState.preferred_clip_length_seconds = nextSec;
  }
  renderAllKeys(true);

  if (backtrackWs && backtrackWs.readyState === WebSocket.OPEN) {
    backtrackWs.send(JSON.stringify({
      action: 'set_clip_duration',
      source: targetSource,
      duration: nextSec
    }));
  }
}

function handleDialPress(context) {
  const entry = actionContexts.get(context);
  if (!entry || !backtrackWs || backtrackWs.readyState !== WebSocket.OPEN) return;

  const source = entry.settings.source || lastKnownSourceMap.get(context) || 'main';
  triggerSavingAnimation(source, context);
  backtrackWs.send(JSON.stringify({ action: 'save_replay', source }));
}

function handleTouchTap(context, payload) {
  const entry = actionContexts.get(context);
  const targetSource = (entry && entry.settings && entry.settings.source) || lastKnownSourceMap.get(context) || 'main';
  const buf = findReplayBuffer(targetSource);

  if (buf) {
    buf.length = 60;
    buf.length_seconds = 60;
  } else {
    backtrackState.preferred_clip_length_seconds = 60;
  }
  renderAllKeys(true);

  if (backtrackWs && backtrackWs.readyState === WebSocket.OPEN) {
    backtrackWs.send(JSON.stringify({
      action: 'set_clip_duration',
      source: targetSource,
      duration: 60
    }));
  }
}

